package br.com.onda;

import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.*;
import android.provider.DocumentsContract;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.util.concurrent.*;

@androidx.media3.common.util.UnstableApi
public class DownloadsActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler handler=new Handler(Looper.getMainLooper());private EditText link;private Button analyze;private TextView status;private LinearLayout choices;private YoutubeDownloads.Option pending;private String title="Onda";private boolean inspecting,picking;
 private final Runnable refresh=new Runnable(){public void run(){if(!inspecting){String value=getSharedPreferences("downloads",0).getString("status","Cole um link para começar.");if(getSharedPreferences("downloads",0).getBoolean("busy",false)&&!MediaDownloadService.activeDownload)value="Operação interrompida. Você pode analisar o link novamente.";status.setText(value);analyze.setEnabled(!MediaDownloadService.activeDownload&&!picking);}handler.postDelayed(this,1000);}};
 @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout root=new LinearLayout(this);root.setOrientation(1);Ui.background(root);root.setOnApplyWindowInsetsListener((v,i)->{root.setPadding(Ui.dp(this,20),Ui.dp(this,12)+i.getSystemWindowInsetTop(),Ui.dp(this,20),Ui.dp(this,12)+i.getSystemWindowInsetBottom());return i;});setContentView(root);
  LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);header.addView(Ui.button(this,"‹",v->finish()),new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,48)));header.addView(Ui.text(this,"Downloads • Lab",23,Ui.TEXT));root.addView(header);
  ScrollView scroll=new ScrollView(this);LinearLayout body=new LinearLayout(this);body.setOrientation(1);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  TextView intro=Ui.text(this,"Cole ou compartilhe um link do YouTube. Use conteúdo seu ou que você tenha autorização para baixar. Esta é uma função experimental; alguns vídeos podem não estar disponíveis.",14,Ui.MUTED);intro.setPadding(0,20,0,20);body.addView(intro);
  link=new EditText(this);Ui.input(link);link.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);link.setHint("https://www.youtube.com/watch?v=…");link.setContentDescription("Link do vídeo");body.addView(link,new LinearLayout.LayoutParams(-1,-2));
  analyze=Ui.button(this,"Analisar link",v->inspect());Ui.primary(analyze);body.addView(analyze,new LinearLayout.LayoutParams(-1,Ui.dp(this,52)));
  status=Ui.text(this,"Cole um link para começar.",14,Ui.CYAN);status.setPadding(0,20,0,20);body.addView(status);choices=new LinearLayout(this);choices.setOrientation(1);body.addView(choices);
  body.addView(Ui.button(this,"Cancelar download",v->{if(MediaDownloadService.activeDownload)startService(new Intent(this,MediaDownloadService.class).setAction("cancel"));}));
  body.addView(Ui.button(this,"Abrir último arquivo",v->openLast()));body.addView(Ui.button(this,"Licença e código-fonte",v->license()));
  TextView note=Ui.text(this,"Áudio: M4A (AAC). Vídeo: MP4 (H.264 + AAC), com as qualidades disponíveis. Sem conversão para MP3 nesta edição.\n\nUm download por vez, até 512 MB e 30 minutos. Você escolhe onde salvar. A notificação permite cancelar; não há tentativas automáticas.\n\nO Onda Lab fica ao lado do Onda Música: para voltar à versão anterior, basta abrir o outro app. As bibliotecas e preferências dos dois apps são separadas. Para levar suas listas, use o backup.",13,Ui.MUTED);note.setPadding(0,20,0,20);body.addView(note);
  if(state!=null)link.setText(state.getString("link",""));else accept(getIntent());
 }
 private void accept(Intent i){if(Intent.ACTION_SEND.equals(i.getAction())){String text=i.getStringExtra(Intent.EXTRA_TEXT);if(text!=null&&text.length()<=4096)link.setText(text);}}
 @Override public void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);accept(intent);}
 private void inspect(){if(inspecting||MediaDownloadService.activeDownload)return;final String url;try{url=DownloadLinks.canonical(link.getText().toString());}catch(IllegalArgumentException e){status.setText(e.getMessage());getSharedPreferences("downloads",0).edit().putString("status",e.getMessage()).apply();return;}
  inspecting=true;analyze.setEnabled(false);choices.removeAllViews();status.setText("Consultando formatos disponíveis…");worker.execute(()->{try{YoutubeDownloads.Result result=YoutubeDownloads.inspect(url);runOnUiThread(()->{if(isDestroyed())return;inspecting=false;analyze.setEnabled(true);title=result.title;String message=title+"\nEscolha um formato para baixar.";getSharedPreferences("downloads",0).edit().putString("status",message).putBoolean("busy",false).apply();status.setText(message);for(YoutubeDownloads.Option o:result.options){Button b=Ui.button(this,o.title,v->pick(o));choices.addView(b,new LinearLayout.LayoutParams(-1,Ui.dp(this,52)));}});}catch(Exception e){runOnUiThread(()->{if(isDestroyed())return;inspecting=false;analyze.setEnabled(true);String message="Não foi possível analisar este vídeo. O YouTube pode exigir verificação, restringir o conteúdo ou ter mudado o serviço. Confira o link e tente mais tarde. O Onda anterior continua disponível.";getSharedPreferences("downloads",0).edit().putString("status",message).putBoolean("busy",false).apply();status.setText(message);android.util.Log.i("OndaDownload","Extraction failed: "+e.getClass().getSimpleName());});}});
 }
 private void pick(YoutubeDownloads.Option option){if(MediaDownloadService.activeDownload||picking)return;pending=option;picking=true;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(option.mime).putExtra(Intent.EXTRA_TITLE,DownloadLinks.filename(title)+"."+option.extension);try{startActivityForResult(i,920);}catch(ActivityNotFoundException e){picking=false;pending=null;status.setText("Seletor de arquivos indisponível.");}}
 @Override public void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);picking=false;if(request!=920)return;YoutubeDownloads.Option option=pending;pending=null;if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri destination=data.getData();try{getContentResolver().takePersistableUriPermission(destination,data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));}catch(SecurityException ignored){}if(option==null||MediaDownloadService.activeDownload){try{DocumentsContract.deleteDocument(getContentResolver(),destination);}catch(Exception ignored){}return;}
  if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},921);
  Intent i=new Intent(this,MediaDownloadService.class).putExtra("first",option.first).putExtra("second",option.second).putExtra("destination",destination.toString()).putExtra("audio","m4a".equals(option.extension));try{startForegroundService(i);choices.removeAllViews();status.setText("Iniciando download…");}catch(RuntimeException e){try{DocumentsContract.deleteDocument(getContentResolver(),destination);}catch(Exception ignored){}status.setText("O Android não permitiu iniciar. Mantenha o Onda Lab aberto e tente novamente.");}
 }
 private void openLast(){String uri=getSharedPreferences("downloads",0).getString("last_uri","");if(uri.isEmpty()){status.setText("Nenhum download concluído ainda.");return;}String mime=getSharedPreferences("downloads",0).getString("last_mime","video/mp4");Intent i=new Intent(Intent.ACTION_VIEW).setDataAndType(Uri.parse(uri),mime).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);if(mime.startsWith("video/"))i.setClass(this,VideoActivity.class);try{startActivity(i);}catch(Exception e){status.setText("Abra o arquivo pelo gerenciador de arquivos do celular.");}}
 private void license(){String text;try(InputStream in=getAssets().open("COPYING")){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);text=out.toString("UTF-8");}catch(IOException e){text="GNU GPL versão 3 ou posterior.";}TextView copy=Ui.text(this,"Onda Lab • modificado em 23/10/2026.\nEsta edição é software livre sob GNU GPL v3 ou posterior, sem garantia. Você pode redistribuir e modificar sob essa licença. Inclui NewPipe Extractor © seus colaboradores. Dependências conservam seus avisos e licenças.\n\n"+text,12,Ui.TEXT);ScrollView scroll=new ScrollView(this);scroll.setPadding(24,16,24,16);scroll.addView(copy);new AlertDialog.Builder(this).setTitle("Licença do Onda Lab").setView(scroll).setNegativeButton("Fechar",null).setPositiveButton("Código-fonte",(d,w)->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://github.com/cristianoarakaki-cpu/Arakaki/tree/onda-lab-downloads/Onda")))).show();}
 @Override public void onSaveInstanceState(Bundle state){state.putString("link",link.getText().toString());super.onSaveInstanceState(state);}
 @Override public void onStart(){super.onStart();handler.post(refresh);}
 @Override public void onStop(){handler.removeCallbacks(refresh);super.onStop();}
 @Override public void onDestroy(){worker.shutdownNow();super.onDestroy();}
}
